import { test, describe } from 'node:test';
import assert from 'node:assert';
import { EventKitReadonlyTransport, parseBridgeDate } from '../src/transport.ts';
import { createMacServerReminderService } from '../src/service.ts';
import { AppError, type MacServerGatewayConfig, type ReminderItem, type RemindersList } from '../src/types.ts';

describe('Swift JSONEncoder Compatibility & Field Fidelity', () => {
  // Exact output generated by Swift `JSONEncoder().encode(lists)`
  const SWIFT_LISTS_JSON = JSON.stringify([
    {
      sourceType: 'calDAV',
      isImmutable: true,
      sourceID: 'source-icloud-test-01',
      color: '#007AFF',
      sourceName: 'iCloud',
      title: 'M****试',
      listID: '9D9A****03F3',
    },
  ]);

  // Exact output generated by Swift `JSONEncoder().encode(items)`
  // Note: dueDate is numeric Cocoa Reference Date (815961600.0), notes is omitted when nil
  const SWIFT_ITEMS_JSON = JSON.stringify([
    {
      dueDate: 815961600, // 2026-11-10T00:00:00.000Z in Cocoa Reference Seconds
      title: 'Swift 合成提醒事项 1',
      isCompleted: false,
      priority: 1,
      itemID: 'item-swift-01',
      listID: '9D9A****03F3',
      notes: '附带备注',
    },
    {
      title: 'Swift 合成提醒事项 2 (无截止日期)',
      isCompleted: true,
      priority: 0,
      itemID: 'item-swift-02',
      listID: '9D9A****03F3',
      // notes and dueDate omitted (nil in Swift)
    },
  ]);

  test('parseBridgeDate converts Swift Cocoa Reference Date (815961600) to ISO string', () => {
    const iso = parseBridgeDate(815961600);
    assert.strictEqual(iso, '2026-11-10T00:00:00.000Z');
  });

  test('Service parses Swift JSONEncoder payload with omitted nil fields and numeric dates', async () => {
    // Custom mock fetch that returns exact Swift JSON output
    const mockFetch = async (input: string | URL | Request) => {
      const url = String(input);
      if (url.endsWith('/reminders/lists')) {
        return new Response(SWIFT_LISTS_JSON, {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }
      if (url.includes('/items')) {
        return new Response(SWIFT_ITEMS_JSON, {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }
      return new Response('Not Found', { status: 404 });
    };

    const config: MacServerGatewayConfig = {
      macserverEndpoint: 'http://127.0.0.1:18765',
      authToken: 'test-token-at-least-32-characters-long!',
      timeoutMs: 2000,
      maxResponseSizeBytes: 1048576,
      allowedLists: [
        {
          listId: '9D9A****03F3',
          expectedSourceId: 'source-icloud-test-01',
          expectedSourceName: 'iCloud',
          expectedSourceType: 'calDAV',
        },
      ],
      expectedSourceType: 'calDAV',
      expectedSourceName: 'iCloud',
    };

    const transport = new EventKitReadonlyTransport(config, mockFetch as unknown as typeof fetch);
    const service = createMacServerReminderService({ transport, config });

    // 1. Verify listLists
    const lists = await service.listLists();
    assert.strictEqual(lists.length, 1);
    assert.strictEqual(lists[0]?.list_id, '9D9A****03F3');
    assert.strictEqual(lists[0]?.name, 'M****试');
    assert.strictEqual(lists[0]?.color, '#007AFF');
    assert.strictEqual(lists[0]?.writable, false);

    // 2. Verify list reminders
    const result = await service.list({});
    assert.strictEqual(result.reminders.length, 2);

    const first = result.reminders[0];
    assert.strictEqual(first?.reminder_id, 'item-swift-01');
    assert.strictEqual(first?.title, 'Swift 合成提醒事项 1');
    assert.strictEqual(first?.due, '2026-11-10T00:00:00.000Z');
    assert.strictEqual(first?.notes, '附带备注');
    assert.strictEqual(first?.completed, false);
    assert.strictEqual(first?.priority, 1);

    const second = result.reminders[1];
    assert.strictEqual(second?.reminder_id, 'item-swift-02');
    assert.strictEqual(second?.title, 'Swift 合成提醒事项 2 (无截止日期)');
    assert.strictEqual(second?.due, undefined);
    assert.strictEqual(second?.notes, undefined);
    assert.strictEqual(second?.completed, true);
    assert.strictEqual(second?.priority, 0);
  });

  test('Cross-list ownership enforcement rejects items returned with foreign listID', async () => {
    const LEAKED_ITEMS_JSON = JSON.stringify([
      {
        title: '恶意泄漏条目',
        isCompleted: false,
        priority: 0,
        itemID: 'item-rogue',
        listID: 'foreign-list-uuid-999', // Mismatched!
      },
    ]);

    const mockFetch = async (input: string | URL | Request) => {
      const url = String(input);
      if (url.endsWith('/reminders/lists')) {
        return new Response(SWIFT_LISTS_JSON, {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }
      return new Response(LEAKED_ITEMS_JSON, {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    };

    const config: MacServerGatewayConfig = {
      macserverEndpoint: 'http://127.0.0.1:18765',
      authToken: 'test-token-at-least-32-characters-long!',
      timeoutMs: 2000,
      maxResponseSizeBytes: 1048576,
      allowedLists: [
        {
          listId: '9D9A****03F3',
          expectedSourceId: 'source-icloud-test-01',
        },
      ],
    };

    const transport = new EventKitReadonlyTransport(config, mockFetch as unknown as typeof fetch);
    const service = createMacServerReminderService({ transport, config });

    await assert.rejects(
      async () => service.list({ list_ids: ['9D9A****03F3'] }),
      (err: unknown) => {
        assert(err instanceof AppError);
        assert.strictEqual(err.code, 'UPSTREAM_ERROR');
        assert(err.message.includes('不匹配'));
        return true;
      }
    );
  });
});
